/* eslint-disable no-undef */
import { Component, Element, Event, EventEmitter, h, Host, Method, Prop, State, Watch } from '@stencil/core';
import { NEXT_BUTTON_LABEL, PREVIOUS_BUTTON_LABEL } from '../../a11y';
import { PaginationDirection } from '../../types';

@Component({
  tag: 'groupui-pagination',
  styleUrl: 'pagination.scss',
  shadow: true,
})
export class Pagination {
  private readonly displayedItemsStartToken = '{displayed-items-start}';
  private readonly displayedItemsEndToken = '{displayed-items-end}';
  private readonly totalItemsToken = '{total-items}';

  /**
   * total elements of the collection across all pages
   */
  @Prop({ reflect: true }) readonly totalElements: number;

  /**
   * current page
   */
  @Prop({ reflect: true, mutable: true }) selectedPage: number = 1;

  /**
   * current pageSize. Must exist in pageSizeOptions
   */
  @Prop({ reflect: true, mutable: true }) pageSize: number = 25;

  /**
   * array of possible pageSizeOptions
   */
  @Prop({ reflect: true }) readonly pageSizeOptions: string = '[5, 10, 25, 50, 1000]';

  /**
   * Number of displayed pages. Minimum is five. Values below five have no effect.
   */
  @Prop() readonly displayedPageCount: number = 5;

  /**
   * text for the elements per side label
   */
  @Prop({ reflect: true }) readonly elementsPerPageLabel: string = 'Items per page';

  /**
   * template text for the currently displayed elements and element quantity.
   * Possible template values:
   *  {displayed-items-start}
   *  {displayed-items-end}
   *  {total-items}
   * e.g.:
   *  'Showing {displayed-items-start} - {displayed-items-end}'
   */
  @Prop({ reflect: true }) readonly visibleElementsLabel: string =
    'Showing {displayed-items-start} - {displayed-items-end}';

  /**
   *  Text for the previous button
   */
  @Prop() readonly previousButtonText: string;

  /**
   *  Text for the next button
   */
  @Prop() readonly nextButtonText: string;

  /**
   * set max-height for the page size options select (e.g. "200px")
   */
  @Prop({ reflect: true }) readonly pageSizeOptionsSelectMaxHeight: string = '15rem';

  /**
   * Flips the order of the elements
   */
  @Prop({ reflect: true }) readonly direction: PaginationDirection = 'default';

  /**
   * aria-label for the previous button. The default value is 'Previous'.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-previous-button' }) readonly a11yLabelPreviousButton: string =
    PREVIOUS_BUTTON_LABEL;

  /**
   * aria-label for the next button. The default value is 'Next'.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-next-button' }) readonly a11yLabelNextButton: string =
    NEXT_BUTTON_LABEL;

  /**
   * aria-label for the select. The default value is 'Select page size'.
   */
  @Prop({ reflect: true, attribute: 'a11y-label-select' }) readonly a11yLabelSelect: string = 'Select page size';

  /**
   * dispatched when the page has changed => 'event.detail' delivers the current page and page size
   */
  @Event({ bubbles: false }) groupuiPageChange: EventEmitter<{ page: number; size: number }>;

  /**
   * dispatched when the pageSize has changed => 'event.detail' delivers the current page size
   */
  @Event({ bubbles: false }) groupuiPageSizeChange: EventEmitter<{ size: number }>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  private pageSelectDropdown!: HTMLGroupuiSelectElement;
  private pageCount: number;

  @State() private pageSizeOptionsState: number[];
  @State() private pageItemsStart: number;
  @State() private pageItemsEnd: number;
  @State() private initSelectedPage: number;

  @Watch('pageSize')
  onPageSizeChanged() {
    this.selectedPage = 1;
    this.groupuiPageSizeChange.emit({ size: this.pageSize });
  }

  @Watch('selectedPage')
  onSelectedPageChanged() {
    this.groupuiPageChange.emit({ page: this.selectedPage, size: this.pageSize });
  }

  @Watch('totalElements')
  onTotalElementsChanged() {
    this.selectedPage = 1;
    this.calcValues();
  }

  /**
   * returns the number of the first item on the currently selected page
   */
  @Method()
  async getPageItemsStart() {
    return this.pageItemsStart;
  }

  /**
   * returns the number of the last item on the currently selected page
   */
  @Method()
  async getPageItemsEnd() {
    return this.pageItemsEnd;
  }

  /**
   * setup internal vars
   */
  componentWillLoad() {
    this.initSelectedPage = this.selectedPage;
    if (typeof this.pageSizeOptions === 'string') {
      this.pageSizeOptionsState = JSON.parse(this.pageSizeOptions);
    } else {
      this.pageSizeOptionsState = this.pageSizeOptions;
    }
    this.calcValues();
  }

  private onPageSizeChangedListener = () => {
    this.selectPageSize(this.pageSelectDropdown.value);
  };

  componentDidLoad() {
    this.groupuiDidLoad.emit();
    this.selectedPage = this.initSelectedPage;
  }

  private selectPageSize(value: string) {
    this.pageSize = parseInt(value);
    this.selectedPage = 1;
    this.calcValues();
  }

  private pageSizeValue() {
    return this.pageSize.toString();
  }

  private selectedPageChanged = (event) => {
    this.selectedPage = event.detail;
    this.calcValues();
  };

  private calcValues() {
    this.calcPageCount();
    this.calcPageItemsStart();
    this.calcPageItemsEnd();
  }

  private calcPageCount() {
    this.pageCount = Math.ceil(this.totalElements / this.pageSize);
  }

  private calcPageItemsStart() {
    if (this.totalElements > 0) {
      this.pageItemsStart = Math.min(
        this.selectedPage > 1 ? (this.selectedPage - 1) * this.pageSize + 1 : this.selectedPage,
        this.totalElements
      );
    } else {
      this.pageItemsStart = 0;
    }
  }

  private calcPageItemsEnd() {
    if (this.totalElements > 0) {
      this.pageItemsEnd = Math.min(this.selectedPage * this.pageSize, this.totalElements);
    } else {
      this.pageItemsEnd = 0;
    }
  }

  render() {
    return (
      <Host>
        <div aria-label="pagination" class="pagination">
          <groupui-simple-pagination
            page-count={this.pageCount}
            displayed-page-count={this.displayedPageCount}
            selected-page={this.selectedPage}
            previous-button-text={this.previousButtonText}
            next-button-text={this.nextButtonText}
            a11y-label-previous-button={this.a11yLabelPreviousButton}
            a11y-label-next-button={this.a11yLabelNextButton}
            onGroupuiPageChange={this.selectedPageChanged}
          ></groupui-simple-pagination>

          <div class="pagination__steps">
            <groupui-text class="pagination__label" size={'body-2'}>
              {this.visibleElementsLabel
                .replace(this.displayedItemsStartToken, `${this.pageItemsStart}`)
                .replace(this.displayedItemsEndToken, `${this.pageItemsEnd}`)
                .replace(this.totalItemsToken, `${this.totalElements}`)}
            </groupui-text>

            <hr aria-orientation="vertical" class="pagination__divider"></hr>

            <groupui-select
              ref={(el) => (this.pageSelectDropdown = el)}
              maxHeight={this.pageSizeOptionsSelectMaxHeight}
              value={this.pageSizeValue()}
              aria-label={this.a11yLabelSelect}
              onGroupuiChange={this.onPageSizeChangedListener}
            >
              {this.pageSizeOptionsState.map((pageSize: number) => (
                <groupui-select-option value={pageSize.toString()}>{pageSize}</groupui-select-option>
              ))}
            </groupui-select>

            <groupui-text class="pagination__itemsLabel" size={'body-2'}>
              {this.elementsPerPageLabel}
            </groupui-text>
          </div>
        </div>
      </Host>
    );
  }
}
